import unittest
from math_utils import safe_divide, median

class MathTests(unittest.TestCase):
    def test_divide(self):
        self.assertEqual(safe_divide(8,2),4)
        with self.assertRaises(ValueError): safe_divide(1,0)
    def test_median(self):
        source=[9,1,5,3]; self.assertEqual(median(source),4); self.assertEqual(source,[9,1,5,3])
        self.assertEqual(median([7,2,4]),4)

if __name__ == '__main__': unittest.main()

import unittest
from parser import parse_records

class ParserTests(unittest.TestCase):
    def test_parse(self):
        self.assertEqual(parse_records('1 | Ada | 9\n\n2|Lin|7\n'), [{'id':'1','name':'Ada','score':9},{'id':'2','name':'Lin','score':7}])
    def test_duplicate(self):
        with self.assertRaises(ValueError): parse_records('1|A|1\n1|B|2\n')

if __name__ == '__main__': unittest.main()

class TaskQueue:
    def __init__(self): self._items=[]
    def add(self, task_id, priority): self._items.append((priority,task_id))
    def pop(self): return self._items.pop()[1]

import unittest
from queueing import TaskQueue

class QueueTests(unittest.TestCase):
    def test_order(self):
        q=TaskQueue(); q.add('b',2); q.add('a',2); q.add('c',5)
        self.assertEqual([q.pop(),q.pop(),q.pop()], ['c','a','b'])
    def test_duplicate(self):
        q=TaskQueue(); q.add('x',1)
        with self.assertRaises(ValueError): q.add('x',9)

if __name__ == '__main__': unittest.main()
